INSERT INTO news (date, lang, title, text) VALUES
 ('2026-11-26', 'es', 'LAIKA 64 3.6: menú con 3 vistas y fondos espaciales', 'BACK cambia el menú entre clásico, barra y lista. Nuevos fondos animados: nebulosas de la NASA, Pilares de la Creación y galaxias. Los ROM hacks usan solos las texturas HD de su juego y la tienda HD muestra sus imágenes al instante. Actualiza desde LAIKA.'),
 ('2026-11-26', 'en', 'LAIKA 64 3.6: menu with 3 views and space backgrounds', 'BACK switches the menu between classic, dock and list. New animated backgrounds: NASA nebulae, Pillars of Creation and galaxies. ROM hacks use their game''s HD textures on their own and the HD store shows its pictures at once. Update from LAIKA.'),
 ('2026-11-26', 'pt', 'LAIKA 64 3.6: menu com 3 visões e fundos espaciais', 'BACK muda o menu entre clássico, barra e lista. Novos fundos animados: nebulosas da NASA, Pilares da Criação e galáxias. Os ROM hacks usam sozinhos as texturas HD do seu jogo e a loja HD mostra as imagens na hora. Atualize pelo LAIKA.'),
 ('2026-11-26', 'fr', 'LAIKA 64 3.6 : menu à 3 vues et fonds spatiaux', 'BACK change le menu : classique, barre ou liste. Nouveaux fonds animés : nébuleuses NASA, Piliers de la Création et galaxies. Les ROM hacks utilisent seuls les textures HD de leur jeu et la boutique HD affiche ses images aussitôt. Mettez à jour depuis LAIKA.'),
 ('2026-11-26', 'it', 'LAIKA 64 3.6: menu con 3 viste e sfondi spaziali', 'BACK cambia il menu tra classico, barra e lista. Nuovi sfondi animati: nebulose NASA, Pilastri della Creazione e galassie. I ROM hack usano da soli le texture HD del loro gioco e il negozio HD mostra subito le immagini. Aggiorna da LAIKA.'),
 ('2026-11-26', 'de', 'LAIKA 64 3.6: Menü mit 3 Ansichten und Weltraum-Hintergründe', 'BACK wechselt das Menü: klassisch, Leiste oder Liste. Neue animierte Hintergründe: NASA-Nebel, Säulen der Schöpfung und Galaxien. ROM-Hacks nutzen von selbst die HD-Texturen ihres Spiels, der HD-Shop zeigt Bilder sofort. Aktualisiere in LAIKA.'),
 ('2026-11-26', 'ru', 'LAIKA 64 3.6: меню с 3 видами и космические фоны', 'BACK переключает меню: классика, панель или список. Новые анимированные фоны: туманности NASA, Столпы творения и галактики. ROM-хаки сами используют HD-текстуры своей игры, а HD-магазин сразу показывает картинки. Обновитесь в LAIKA.');
